head.script:
scwin.screenId = "jldfil25304";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_befLogin", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "befLogin" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("befLogin")) !== 'OK'); } }, { id: "if_befLogin_2", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "befLogin" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("befLogin")) === 'OK'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil25304.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_CROSSWEBEX_INSTALL_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_CROSSWEBEX_INSTALL_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_CROSSWEBEX_INSTALL_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        CROSSWEBEX_INSTALL.download('crosswebex','client')
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25304.btn_CROSSWEBEX_INSTALL_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.installCheckCallback
 * @author Inswave
 * @date 2026. 09. 29
 * @param result
 * @returns
 * @hidden N
*/
scwin.installCheckCallback = async function (result) {
    /* sdd-asis-lifecycle:begin installCheckCallback — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (result) {
        await $c.win.alert(CROSSWEBEX_UTIL.loadStringTable().WARN.C_W_030);
        (function () { const o = $c.win.getOpenerScope(); if (o) { $c.win.setPageFrameSrc($c.win.getFrame(o), null); } else { console.error('[sdd] 부모 창을 못 찾았다 — 새로고침하지 않는다(자기 화면을 다시 열면 무한 고리가 된다)'); } })();
        $c.win.closePopup();
    } else {
        if (!CROSSWEBEX_CHECK.chkInfoStatus.status) {
            const info = CROSSWEBEX_CHECK.chkInfoStatus.info[0];
            if (CROSSWEBEX_UTIL.typeExtension()) {
                if (!info.extension) {
                    extDown.style.display = "block";
                } else {
                    extDown.style.display = "none";
                    cliDown.style.margin = "80px";
                }
            }
            if (!info.EX || !info.client) {
                if (CROSSWEBEX_UTIL.isLinux()) {
                    linuxDown.style.display = "block";
                } else {
                    cliDown.style.display = "block";
                }
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};
